import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.B-kZW7D6.js";const h=JSON.parse(`{"title":"Marvellous updates on ZLUDA","description":"And you, Vosen, you're the real hero!","frontmatter":{"title":"Marvellous updates on ZLUDA","description":"And you, Vosen, you're the real hero!","tags":["GPU","虚拟化"]},"headers":[],"relativePath":"zh/blogs/20240215/index.md","filePath":"zh/blogs/20240215/index.md"}`),s={name:"zh/blogs/20240215/index.md"};function n(i,e,l,p,u,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<nav class="table-of-contents"><ul></ul></nav><p>ZLUDA once lets you run unmodified CUDA applications on Intel devices. Several days ago, it introduces an explosive update, and now it only supports AMD.</p><p>For me, the most exciting part would be the more complete <a href="https://github.com/vosen/ZLUDA/blob/master/zluda_dark_api/src/lib.rs" target="_blank" rel="noreferrer">CUDA dark api</a>. Great advances have been reached compared with three years ago, when Vosen announce stopping working on this project. More inner CUDA calls are reversed and revealed to the public.</p><p>Other related projects I&#39;m tracking:</p><ul><li><a href="https://github.com/gvirtus/GVirtuS" target="_blank" rel="noreferrer">https://github.com/gvirtus/GVirtuS</a> (After three years, it updates recently, too!)</li><li><a href="https://github.com/google/gvisor/issues/14" target="_blank" rel="noreferrer">https://github.com/google/gvisor/issues/14</a> (Track the GPU support proposal for gVisor.)</li></ul>',5)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
